// pedido-numerado.js: esta cliente já tem pergunta à dona sem resposta? Então não manda outra (a dona reclama de pergunta demais)
const r = $('Recebe pergunta da IA').first().json;
const fim8 = (t) => String(t || '').replace(/\D/g, '').slice(-8);
const meus = Object.values($('Pedido nº: abertos').first().json || {}).map((v) => { try { return typeof v === 'string' ? JSON.parse(v) : v; } catch (e) { return null; } }).filter((p) => p && typeof p === 'object' && p.empresa === 'ff4b7937-1abb-4803-83c8-e0896d94fc9f' && p.telefone && p.pergunta).filter((p) => fim8(p.telefone) === fim8(r.telefone) && (p.tipo || 'pergunta') === (r.tipo || 'pergunta'));
return [{ json: { aberto: meus.sort((a, b) => (b.criado || 0) - (a.criado || 0))[0] || null } }];
